        "items": [
          {
            "number": 1,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Uses more than one relevant evidence clue to reason about whether an example is a living organism and explicitly rejects movement, growth, energy use, or appearance alone as proof of life.",
            "criterionLabel": "Multiple evidence clues for life",
            "requiredCore": true
          },
          {
            "number": 2,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Explains that living things use resources/energy and show life processes while recognizing that plants, animals, fungi, and tiny organisms can meet needs or respond in different ways.",
            "criterionLabel": "Living needs and diversity",
            "requiredCore": true
          },
          {
            "number": 3,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Distinguishes a currently living organism from once-living or living-derived material and from a never-living example, using evidence about present state or origin.",
            "criterionLabel": "Living / once-living / never-living distinction",
            "requiredCore": true
          },
          {
            "number": 4,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "States a classification rule before sorting, applies it consistently, and uses a need-more-evidence category rather than guessing when information is insufficient.",
            "criterionLabel": "Rule-first classification with uncertainty",
            "requiredCore": true
          },
          {
            "number": 5,
            "domain": "Mathematics",
            "points": 1,
            "prompt": "Tallies a provided classification set accurately, builds or interprets an accessible simple graph, compares categories, checks totals, and limits claims to the provided sample.",
            "criterionLabel": "Tally graph and sample reasoning",
            "requiredCore": true
          },
          {
            "number": 6,
            "domain": "Mathematics",
            "points": 1,
            "prompt": "Uses at least one robot, fire, crystal, model, or comparable counterexample to show why a one-clue life rule fails and replaces it with stronger multi-evidence reasoning.",
            "criterionLabel": "Counterexample reasoning",
            "requiredCore": true
          },
          {
            "number": 7,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Explains that a viable dormant seed can be alive without visible growth and that appearance alone may justify a need-more-evidence conclusion rather than certainty.",
            "criterionLabel": "Dormancy and hidden-evidence reasoning",
            "requiredCore": true
          },
          {
            "number": 8,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Distinguishes a representation/model from a living organism and identifies at least one limitation of visual appearance or a classroom model.",
            "criterionLabel": "Model and observation limits",
            "requiredCore": false
          },
          {
            "number": 9,
            "domain": "Social-Emotional / Safety",
            "points": 1,
            "prompt": "Knows that proving life never requires harming/depriving organisms, tasting specimens, culturing unknown microbes/mold, or handling unknown plants/fungi/wildlife/remains; safe models, records, and observation are valid evidence.",
            "criterionLabel": "Humane safety and care boundary",
            "requiredCore": true
          },
          {
            "number": 10,
            "domain": "Inquiry / Evidence",
            "points": 1,
            "prompt": "Integrates multi-clue evidence, once/never history, classification/data, uncertainty, a counterexample, and humane observation in an accessible explanation or model.",
            "criterionLabel": "Integrated living-systems explanation",
            "requiredCore": true
          }
        ],
